use sea_orm_migration::prelude::*;
use sea_orm_migration::schema::{boolean, boolean_null};
use sea_orm_migration_sqlite::{SchemaManagerExt, TableExt};

use crate::foreign_key::{disable_foreign_key_checks, enable_foreign_key_checks};
use crate::migrations::m20260417_150300_initial::Identifier;
use crate::supported_db_type::{SupportedDbType, WithSupportedDbType};

#[derive(DeriveMigrationName)]
pub struct Migration;

// Identifiers created automatically by the core (holder batch credential binding keys) are named
// with this prefix. did:webvh update keys are also autogenerated, but as of this migration they
// are never wrapped in their own `identifier` row (they only exist in `key`/`key_did`), so the
// UPDATE_KEY branch below currently matches nothing in practice. It is kept defensively for a
// KEY-type identifier that references such a key via `identifier.key_id`, should a future code
// path start creating one.
const BACKFILL_SQL: &str = r#"
UPDATE identifier
SET autogenerated = (
    name LIKE 'autogenerated-%'
    OR EXISTS (
        SELECT 1 FROM key_did
        WHERE key_did.key_id = identifier.key_id
          AND key_did.role = 'UPDATE_KEY'
    )
)
"#;

#[async_trait::async_trait]
impl MigrationTrait for Migration {
    async fn up(&self, manager: &SchemaManager) -> Result<(), DbErr> {
        disable_foreign_key_checks(manager).await?;
        if manager.supported_db_type() == SupportedDbType::Sqlite {
            self.up_sqlite(manager).await?;
        } else {
            self.up_sane(manager).await?;
        }
        enable_foreign_key_checks(manager).await?;

        Ok(())
    }
}

impl Migration {
    async fn up_sane(&self, manager: &SchemaManager<'_>) -> Result<(), DbErr> {
        manager
            .alter_table(
                Table::alter()
                    .table(Identifier::Table)
                    .add_column(boolean_null(Col::Autogenerated))
                    .to_owned(),
            )
            .await?;

        manager
            .get_connection()
            .execute_unprepared(BACKFILL_SQL)
            .await?;

        manager
            .alter_table(
                Table::alter()
                    .table(Identifier::Table)
                    .modify_column(boolean(Col::Autogenerated))
                    .to_owned(),
            )
            .await
    }

    async fn up_sqlite(&self, manager: &SchemaManager<'_>) -> Result<(), DbErr> {
        manager
            .recreate_table(
                Table::recreate()
                    .table(Identifier::Table)
                    .add_column_with_value(boolean(Col::Autogenerated), Expr::value(false))
                    .to_owned(),
            )
            .await?;

        manager
            .get_connection()
            .execute_unprepared(BACKFILL_SQL)
            .await?;
        Ok(())
    }
}

#[derive(DeriveIden)]
enum Col {
    Autogenerated,
}
